use std::marker::PhantomData;use tokio_util::bytes::{Bytes, BytesMut};#[derive(Clone)]pub struct LengthDelimitedCodec<T> {    config: bincode::config::Configuration,    length_codec: tokio_util::codec::LengthDelimitedCodec,    phantom_data: PhantomData<T>}impl<T> Default for LengthDelimitedCodec<T> {    fn default() -> Self {        LengthDelimitedCodec {            config: bincode::config::standard(),            length_codec: tokio_util::codec::LengthDelimitedCodec::builder()                .length_field_length(4)                .max_frame_length(u32::MAX as usize)                .new_codec(),            phantom_data: PhantomData::default()        }    }}impl<T: bincode::Decode<()>> tokio_util::codec::Decoder for LengthDelimitedCodec<T> {    type Item = T;    type Error = std::io::Error;    fn decode(&mut self, src: &mut BytesMut) -> Result<Option<Self::Item>, Self::Error> {        let frame = match self.length_codec.decode(src).map_err(|_| std::io::Error::new(std::io::ErrorKind::InvalidData, "Failed to decode length-delimited data"))? {            Some(frame) => frame,            None => return Ok(None),        };        let (message, _) =            bincode::decode_from_slice(&frame, self.config).map_err(|_| std::io::Error::new(std::io::ErrorKind::InvalidData, "Failed to decode length-delimited data"))?;                Ok(Some(message))    }}impl<T: bincode::Encode> tokio_util::codec::Encoder<T> for LengthDelimitedCodec<T> {    type Error = std::io::Error;    fn encode(&mut self, item: T, dst: &mut BytesMut) -> Result<(), Self::Error> {        let encoded_data = bincode::encode_to_vec(&item, self.config).map_err(|_| {            std::io::Error::new(std::io::ErrorKind::InvalidData, "Failed to encode data")        })?;        self.length_codec            .encode(Bytes::from(encoded_data), dst)            .map_err(|_| {                std::io::Error::new(                    std::io::ErrorKind::InvalidData,                    "Couldn't encode length-delimited data",                )            })?;                Ok(())    }}